    /// A core profile 4.1 context without a window, with llrender set up as the viewer and the
    /// golden-image program set it up on macOS. Made once for all the tests.
    class GLContext
    {
    public:
        GLContext()
        {
            LLCommon::initClass();
            LLRender::sGLCoreProfile = true;
            CGLPixelFormatAttribute attribs[] = {
                kCGLPFAOpenGLProfile, (CGLPixelFormatAttribute)kCGLOGLPVersion_GL4_Core,
                kCGLPFAAccelerated,
                kCGLPFANoRecovery,
                kCGLPFAColorSize, (CGLPixelFormatAttribute)24,
                kCGLPFAAlphaSize, (CGLPixelFormatAttribute)8,
                kCGLPFADepthSize, (CGLPixelFormatAttribute)24,
                (CGLPixelFormatAttribute)0
            };
            CGLPixelFormatObj format = nullptr;
            GLint count = 0;
            if (CGLChoosePixelFormat(attribs, &format, &count) != kCGLNoError || !format)
            {
                return;
            }
            const CGLError error = CGLCreateContext(format, nullptr, &mContext);
            CGLDestroyPixelFormat(format);
            if (error != kCGLNoError || CGLSetCurrentContext(mContext) != kCGLNoError)
            {
                return;
            }
            if (!gGLManager.initGL())
            {
                return;
            }
            LLVertexBuffer::initClass(nullptr);
            if (!gGL.init(true))
            {
                return;
            }
            LLImageGL::initClass(nullptr, 1, false, false, false);
            // The white texture LLTexUnit::unbind leaves bound, as the viewer makes it.
            glGenTextures(1, &LLTexUnit::sWhiteTexture);
            glBindTexture(GL_TEXTURE_2D, LLTexUnit::sWhiteTexture);
            const U8 white[4] = { 255, 255, 255, 255 };
            glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, 1, 1, 0, GL_RGBA, GL_UNSIGNED_BYTE, white);
            glBindTexture(GL_TEXTURE_2D, 0);
            mReady = true;
        }

        ~GLContext()
        {
            if (mReady)
            {
                glDeleteTextures(1, &LLTexUnit::sWhiteTexture);
                LLTexUnit::sWhiteTexture = 0;
                gGL.shutdown();
                LLVertexBuffer::cleanupClass();
                LLImageGL::cleanupClass();
            }
            if (mContext)
            {
                CGLSetCurrentContext(nullptr);
                CGLDestroyContext(mContext);
            }
        }

        bool ready() const { return mReady; }

    private:
        CGLContextObj mContext = nullptr;
        bool mReady = false;
    };

    GLContext& glContext()
    {
        static GLContext context;
        return context;
    }

    Ref<Device> glDevice()
    {
        DeviceCreateInfo info;
        info.backend.type = BackendType::GL;
        return Device::create(info);
    }

    GLint textureLevel(GLenum target, GLenum face, U32 level, GLenum name)
    {
        GLint value = 0;
        glGetTexLevelParameteriv(face ? face : target, level, name, &value);
        return value;
    }

    GLint integer(GLenum name)
    {
        GLint value = 0;
        glGetIntegerv(name, &value);
        return value;
    }

    /// Unbinds and frees a raw LLRenderTarget. flush() binds framebuffer 0 with GL_BACK, which a
    /// context without a window refuses, so its errors are dropped here, after the test's checks.
    void releaseRaw(LLRenderTarget& raw)
    {
        raw.flush();
        raw.release();
        while (glGetError() != GL_NO_ERROR)
        {
        }
    }

    /// LLGLState's cache of the enables a pass can change, against GL, as LLGLState::checkStates
    /// compares them under gDebugGL. Empty when they match.
    struct StateCache : public LLGLState
    {
        static std::string mismatch()
        {
            const LLGLenum states[] = { GL_BLEND, GL_SCISSOR_TEST, GL_CULL_FACE, GL_POLYGON_OFFSET_FILL,
                                        GL_POLYGON_OFFSET_LINE, GL_DEPTH_CLAMP };
            for (LLGLenum state : states)
            {
                if ((sStateMap[state] == GL_TRUE) != (glIsEnabled(state) == GL_TRUE))
                {
                    return llformat("state 0x%04x", state);
                }
            }
            return {};
        }
    };

    /// The index of a reflected uniform, or the reflection's size when there is none.
    U32 uniformIndex(const Program& program, const std::string& name)
    {
        const std::vector<UniformInfo>& uniforms = program.reflection().uniforms;
        U32 index = 0;
        while (index < uniforms.size() && uniforms[index].name != name)
        {
            ++index;
        }
        return index;
    }

    /// LLShaderMgr::mReservedAttribs, in its order, as the facades will pass them.
    const std::vector<std::string> RESERVED_ATTRIBUTES = {
        "position", "normal", "texcoord0", "texcoord1", "texcoord2", "texcoord3", "diffuse_color",
        "emissive", "tangent", "weight", "weight4", "clothing", "joint", "texture_index" };

    const char* VERTEX = R"(#version 410
in vec3 position;
in vec4 diffuse_color;
in vec2 texcoord0;
uniform mat4 modelview_projection_matrix;
out vec4 vertex_color;
out vec2 vary_texcoord0;
void main()
{
    gl_Position = modelview_projection_matrix * vec4(position, 1.0);
    vertex_color = diffuse_color;
    vary_texcoord0 = texcoord0;
}
)";

    const char* FRAGMENT = R"(#version 410
uniform sampler2D diffuseMap;
uniform samplerCube environmentMap;
uniform float alpha_scale[4];
layout (std140) uniform Lights
{
    vec4 light_color[8];
};
vec4 tint(vec4 color);
in vec4 vertex_color;
in vec2 vary_texcoord0;
out vec4 frag_color;
void main()
{
    vec4 color = texture(diffuseMap, vary_texcoord0) * vertex_color + texture(environmentMap, vec3(1.0)) * 0.0;
    frag_color = tint(color) * alpha_scale[3] + light_color[7] * 0.0;
}
)";

    // A second fragment unit, as LLShaderMgr links feature objects into a stage.
