    // Programs, pipelines and depth state ----------------------------------------------------

    template<> template<>
    void object::test<9>()
    {
        set_test_name("programs link from their units and reflect as mapUniforms reads them");
        Ref<Device> device = glDevice();
        Ref<Program> program = device->createProgram(programDesc("uiProgram"));
        ensure("linked", program.notNull());
        ensure("ready at once on GL", program->status() == CompileStatus::Ready);
        ensure("a GL program", glIsProgram(GLNames::of(program)));
        ensure_equals("named", program->debugName(), std::string("uiProgram"));

        const ProgramReflection& reflection = program->reflection();
        auto find = [&reflection](const std::string& name) -> const UniformInfo*
        {
            for (const UniformInfo& uniform : reflection.uniforms)
            {
                if (uniform.name == name)
                {
                    return &uniform;
                }
            }
            return nullptr;
        };
        ensure("matrix", find("modelview_projection_matrix") && find("modelview_projection_matrix")->type == UniformType::Mat4);
        ensure("sampler", find("diffuseMap") && find("diffuseMap")->type == UniformType::Sampler2D);
        ensure("cube sampler", find("environmentMap") && find("environmentMap")->type == UniformType::SamplerCube);
        const UniformInfo* scale = find("alpha_scale");
        ensure("array named without [0]", scale != nullptr);
        ensure_equals("array size", scale->arraySize, 4u);
        ensure("block members are not loose uniforms", find("light_color") == nullptr);
        ensure_equals("one block", reflection.blocks.size(), 1u);
        ensure_equals("block name", reflection.blocks[0].name, std::string("Lights"));
        ensure_equals("block size", reflection.blocks[0].size, 128u);
        const U32 expected = (1u << 0) | (1u << 2) | (1u << 6); // position, texcoord0, diffuse_color
        ensure_equals("attributes the program reads", reflection.attributeMask, expected);
        GLint location = -1;
        location = glGetAttribLocation(GLNames::of(program), "diffuse_color");
        ensure_equals("reserved attributes have fixed locations", location, 6);
    }

    template<> template<>
    void object::test<10>()
    {
        set_test_name("a program that does not compile is null, with the stage and GL's log");
        Ref<Device> device = glDevice();
        CaptureLog log(LLError::LEVEL_WARN);
        ProgramDesc broken = programDesc("brokenProgram");
        broken.stages[1].units[0] = "#version 410\nvoid main() { this is not GLSL; }\n";
        ensure("null", device->createProgram(broken).isNull());
        log.messageWith("Could not create program 'brokenProgram': fragment unit 0 does not compile");
        ensure_equals("no GL error left by it", glGetError(), GLenum(GL_NO_ERROR));

        ProgramDesc unlinked = programDesc("unlinkedProgram");
        unlinked.stages[1].units.pop_back(); // tint() is declared but never defined
        ensure("null when it does not link", device->createProgram(unlinked).isNull());
        log.messageWith("Could not create program 'unlinkedProgram': it does not link");
        ensure_equals("no GL error left", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<11>()
    {
        set_test_name("pipelines are cached per program, and go with their program");
        Ref<Device> device = glDevice();
        Ref<Program> program = device->createProgram(programDesc("uiProgram"));
        PipelineDesc desc;
        desc.attributeMask = program->reflection().attributeMask;
        desc.colorFormats[0] = Format::RGBA8Unorm;
        desc.depthFormat = Format::Depth32Float;
        Ref<Pipeline> first = device->getPipeline(*program, desc);
        ensure("pipeline", first.notNull());
        ensure("cached", device->getPipeline(*program, desc).get() == first.get());
        desc.blend.enabled = true;
        desc.blend.srcColor = BlendFactor::SourceAlpha;
        desc.blend.dstColor = BlendFactor::OneMinusSourceAlpha;
        ensure("another with blending", device->getPipeline(*program, desc).get() != first.get());
        ensure_equals("for this program", first->programId(), program->id());

        const GLuint name = GLNames::of(program);
        program = nullptr;
        ensure("the program is deleted", !glIsProgram(name));
        ensure_equals("a held pipeline still knows its program's id", first->programId() != 0, true);
    }

    template<> template<>
    void object::test<12>()
    {
        set_test_name("depth states are cached, and geometry shaders link on GL");
        Ref<Device> device = glDevice();
        DepthStencilDesc test{ true, true, CompareFunc::LessEqual };
        ensure("cached", device->getDepthStencilState(test).get() == device->getDepthStencilState(test).get());
        ensure("described", device->getDepthStencilState(test)->desc() == test);

        ProgramDesc normals = programDesc("normalDebugProgram");
        normals.stages.insert(normals.stages.begin() + 1, StageSource{ ShaderStage::Geometry, { R"(#version 410
layout (triangles) in;
layout (triangle_strip, max_vertices = 3) out;
in vec4 vertex_color[];
in vec2 vary_texcoord0[];
out vec4 g_vertex_color;
out vec2 g_texcoord0;
void main()
{
    for (int i = 0; i < 3; ++i)
    {
        gl_Position = gl_in[i].gl_Position;
        EmitVertex();
    }
    EndPrimitive();
}
)" } });
        // The fragment stage reads what the geometry stage writes under other names, so give it
        // a fragment stage of its own.
        normals.stages[2].units = { R"(#version 410
out vec4 frag_color;
void main() { frag_color = vec4(1.0); }
)" };
        ensure("geometry shaders on GL", device->capabilities().geometryShaders);
        ensure("linked", device->createProgram(normals).notNull());
    }

    // The encoder ------------------------------------------------------------------------------

    template<> template<>
    void object::test<13>()
    {
        set_test_name("a pass clears with its load action and gives LLRenderTarget its framebuffer and viewport back");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        LLRenderTarget raw;
        ensure("a raw target", raw.allocate(32, 32, GL_RGBA));
        raw.bindTarget();
        const U32 previous = LLRenderTarget::sCurFBO;
        ensure("raw GL has a framebuffer bound", previous != 0);
        RenderPassDesc pass = scene.pass();
        pass.color[0].clear = { 0.25f, 0.5f, 0.75f, 1.f };
        encoder.beginRenderPass(pass);
        ensure("our framebuffer is LLRenderTarget's current", LLRenderTarget::sCurFBO != previous);
        ensure_equals("the pass's size", LLRenderTarget::sCurResX, 64u);
        encoder.endRenderPass();
        ensure_equals("back to the previous framebuffer", LLRenderTarget::sCurFBO, previous);
        ensure_equals("and bound", integer(GL_FRAMEBUFFER_BINDING), GLint(previous));
        ensure_equals("its size", LLRenderTarget::sCurResX, 32u);
        GLint viewport[4] = {};
        glGetIntegerv(GL_VIEWPORT, viewport);
        ensure("its viewport", viewport[0] == 0 && viewport[1] == 0 && viewport[2] == 32 && viewport[3] == 32);
        const std::array<U8, 4> pixel = scene.pixel(10, 10);
        ensure("cleared: " + text(pixel), near(pixel, { 64, 128, 191, 255 }));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
        releaseRaw(raw);
    }

    template<> template<>
    void object::test<14>()
    {
        set_test_name("a draw with a pipeline, vertex colors and a uniform matrix");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        const Quad red = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 0, 0, 255 });
        Ref<Buffer> buffer = scene.vertices(red);
        Ref<Pipeline> pipeline = scene.pipeline(*scene.color);
        encoder.beginRenderPass(scene.pass());
        encoder.setPipeline(pipeline.get());
        encoder.setDepthStencilState(scene.device->getDepthStencilState({ true, true, CompareFunc::LessEqual }).get());
        encoder.setUniform(scene.color.get(), 0, { reinterpret_cast<const std::byte*>(IDENTITY), sizeof(IDENTITY) });
        encoder.setVertexBuffer(buffer.get(), red.streams);
        encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
        encoder.endRenderPass();
        const std::array<U8, 4> pixel = scene.pixel(32, 32);
        ensure("red: " + text(pixel), near(pixel, { 255, 0, 0, 255 }));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<15>()
    {
        set_test_name("indexed draws with the depth test, in both orders");
        for (int order = 0; order < 2; ++order)
        {
            Scene scene;
            Encoder& encoder = scene.device->encoder();
            const Quad nearQuad = quad(-1.f, -1.f, 1.f, 1.f, -0.5f, { 0, 255, 0, 255 });
            const Quad farQuad = quad(-1.f, -1.f, 1.f, 1.f, 0.5f, { 255, 0, 0, 255 });
            Ref<Buffer> nearBuffer = scene.vertices(nearQuad);
            Ref<Buffer> farBuffer = scene.vertices(farQuad);
            const U16 indices[6] = { 0, 1, 2, 2, 1, 3 };
            BufferDesc indexDesc;
            indexDesc.size = sizeof(indices);
            indexDesc.usage = BUFFER_INDEX;
            Ref<Buffer> indexBuffer = scene.device->createBuffer(indexDesc, std::as_bytes(std::span(indices)), "indices");
            encoder.beginRenderPass(scene.pass());
            encoder.setPipeline(scene.pipeline(*scene.color).get());
            encoder.setDepthStencilState(scene.device->getDepthStencilState({ true, true, CompareFunc::LessEqual }).get());
            encoder.setUniform(scene.color.get(), 0, { reinterpret_cast<const std::byte*>(IDENTITY), sizeof(IDENTITY) });
            encoder.setIndexBuffer(indexBuffer.get(), IndexType::U16);
            Ref<Buffer> first = order == 0 ? farBuffer : nearBuffer;
            Ref<Buffer> second = order == 0 ? nearBuffer : farBuffer;
            encoder.setVertexBuffer(first.get(), nearQuad.streams);
            encoder.drawIndexed(PrimitiveType::Triangles, 0, 6);
            encoder.setVertexBuffer(second.get(), nearQuad.streams);
            encoder.drawIndexed(PrimitiveType::Triangles, 0, 6);
            encoder.endRenderPass();
            const std::array<U8, 4> pixel = scene.pixel(32, 32);
            ensure("the near quad wins (order " + std::to_string(order) + "): " + text(pixel),
                   near(pixel, { 0, 255, 0, 255 }));
        }
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<16>()
    {
        set_test_name("a texture's sampling lands on its own channel, and nothing bound reads nothing");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        Ref<Texture> checker = scene.device->createTexture(texture2D(2, 2), "checker");
        encoder.uploadTexture(checker.get(), 0, 0, { 0, 0, 2, 2 }, PixelLayout(), std::as_bytes(std::span(CHECKER)));
        Ref<Texture> other = scene.device->createTexture(texture2D(2, 2), "other");
        // The checker is on channel 3 already and unit 0 is active, so binding the checker again
        // does not make unit 3 active by itself.
        GLNames::bind(gGL.getTexUnit(3), LLTexUnit::TT_TEXTURE, GLNames::of(checker));
        GLNames::bind(gGL.getTexUnit(0), LLTexUnit::TT_TEXTURE, GLNames::of(other));
        const Quad q = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 255, 255, 255 });
        Ref<Buffer> buffer = scene.vertices(q);
        encoder.beginRenderPass(scene.pass(true, false));
        encoder.setPipeline(scene.pipeline(*scene.textured, false).get());
        encoder.setDepthStencilState(nullptr);
        encoder.setSamplerChannel(scene.textured.get(), 0, 3);
        SamplerDesc point;
        point.filter = Filter::Point;
        point.addressU = point.addressV = point.addressW = AddressMode::ClampToEdge;
        encoder.setTexture(3, checker.get(), point);
        encoder.setVertexBuffer(buffer.get(), q.streams);
        encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
        encoder.endRenderPass();
        ensure("bottom left red: " + text(scene.pixel(8, 8)), near(scene.pixel(8, 8), { 255, 0, 0, 255 }));
        ensure("bottom right green", near(scene.pixel(56, 8), { 0, 255, 0, 255 }));
        ensure("top left blue", near(scene.pixel(8, 56), { 0, 0, 255, 255 }));
        ensure("top right white", near(scene.pixel(56, 56), { 255, 255, 255, 255 }));
        // Bilinear filtering would mix red and green here.
        ensure("point filtered next to the middle: " + text(scene.pixel(28, 8)), near(scene.pixel(28, 8), { 255, 0, 0, 255 }));
        gGL.getTexUnit(0)->activate();
        GLint filter = 0;
        glGetTexParameteriv(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, &filter);
        ensure_equals("unit 0's texture keeps its filter", filter, GLint(GL_LINEAR));

        // Nothing on the channel, after raw GL left the unit with its white texture: the draw reads
        // (0, 0, 0, 1), not white.
        encoder.setTexture(3, nullptr, point);
        gGL.getTexUnit(3)->unbind(LLTexUnit::TT_TEXTURE);
        RenderPassDesc grey = scene.pass(true, false);
        grey.color[0].clear = { 0.5f, 0.5f, 0.5f, 1.f };
        encoder.beginRenderPass(grey);
        encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
        encoder.endRenderPass();
        ensure("black: " + text(scene.pixel(32, 32)), near(scene.pixel(32, 32), { 0, 0, 0, 255 }));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<17>()
    {
        set_test_name("a pass is a scope for GL state: raw GL in it sees the interface's, and after it its own");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        LLRenderTarget raw;
        ensure("a raw target", raw.allocate(64, 64, GL_RGBA, true));
        raw.bindTarget();
        const U32 rawFramebuffer = LLRenderTarget::sCurFBO;
        const GLint depthFunc = integer(GL_DEPTH_FUNC);
        LLGLSLShader rawShader;
        GLNames::assign(rawShader, GLNames::of(scene.textured));
        rawShader.bind();

        const bool debugGL = gDebugGL;
        gDebugGL = true; // so LLGLDepthTest checks its cache against GL
        WrapLLErrs errors;
        const std::string error = errors.catch_llerrs([&]
        {
            // Raw GL's state before the pass.
            LLGLEnable blend(GL_BLEND);
            gGL.blendFunc(LLRender::BF_ONE, LLRender::BF_ONE);
            gGL.setColorMask(true, false);
            glScissor(1, 2, 3, 4);

            encoder.beginRenderPass(scene.pass());
            encoder.setPipeline(scene.pipeline(*scene.color).get()); // no blending
            encoder.setDepthStencilState(scene.device->getDepthStencilState({ true, false, CompareFunc::Greater }).get());
            encoder.setScissor(true, 0, 0, 32, 32);
            encoder.setCullMode(CullMode::Front);
            encoder.setFillMode(FillMode::Lines);
            encoder.setDepthBias(1.f, 2.f, true, false);
            encoder.setPointSize(4.f);
            ensure("the pipeline's blending", !glIsEnabled(GL_BLEND));
            ensure("the depth test", glIsEnabled(GL_DEPTH_TEST));
            {
                // Raw code's scopes see the state the interface set, and put it back.
                LLGLEnable rawBlend(GL_BLEND);
                LLGLDepthTest noDepth(GL_FALSE);
                ensure("blending on in the scope", glIsEnabled(GL_BLEND));
                ensure("depth off in the scope", !glIsEnabled(GL_DEPTH_TEST));
            }
            ensure("blending off again", !glIsEnabled(GL_BLEND));
            ensure("depth on again", glIsEnabled(GL_DEPTH_TEST));
            encoder.endRenderPass();

            ensure_equals("the raw target is current again", LLRenderTarget::sCurFBO, rawFramebuffer);
            ensure("raw GL's blending", glIsEnabled(GL_BLEND));
            ensure("and its function", integer(GL_BLEND_SRC_RGB) == GL_ONE && integer(GL_BLEND_DST_RGB) == GL_ONE);
            GLboolean mask[4] = {};
            glGetBooleanv(GL_COLOR_WRITEMASK, mask);
            ensure("its color mask", mask[0] && mask[1] && mask[2] && !mask[3]);
            ensure("no depth test", !glIsEnabled(GL_DEPTH_TEST));
            GLboolean write = GL_FALSE;
            glGetBooleanv(GL_DEPTH_WRITEMASK, &write);
            ensure("depth writes", write == GL_TRUE);
            ensure_equals("the depth function", integer(GL_DEPTH_FUNC), depthFunc);
            ensure("no scissor", !glIsEnabled(GL_SCISSOR_TEST));
            GLint box[4] = {};
            glGetIntegerv(GL_SCISSOR_BOX, box);
            ensure("raw GL's scissor box", box[0] == 1 && box[1] == 2 && box[2] == 3 && box[3] == 4);
            ensure("no culling", !glIsEnabled(GL_CULL_FACE));
            ensure_equals("the cull face", integer(GL_CULL_FACE_MODE), GLint(GL_BACK));
            GLint fill[2] = {};
            glGetIntegerv(GL_POLYGON_MODE, fill);
            ensure_equals("filled polygons", fill[0], GLint(GL_FILL));
            ensure("no depth bias", !glIsEnabled(GL_POLYGON_OFFSET_FILL));
            GLfloat pointSize = 0.f;
            glGetFloatv(GL_POINT_SIZE, &pointSize);
            ensure_equals("the point size", pointSize, 1.f);
            ensure("raw GL's shader is current", LLGLSLShader::sCurBoundShaderPtr == &rawShader);
            ensure_equals("and its program", LLGLSLShader::sCurBoundShader, GLNames::of(rawShader));
            ensure_equals("bound", integer(GL_CURRENT_PROGRAM), GLint(GLNames::of(rawShader)));
            ensure_equals("LLGLState's cache matches GL", StateCache::mismatch(), std::string());
            LLGLDepthTest check(GL_FALSE); // checks LLGLDepthTest's cache against GL
            ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
        });
        gDebugGL = debugGL;
        ensure_equals("no LL_ERRS", error, std::string());
        gGL.setColorMask(true, true);
        gGL.blendFunc(LLRender::BF_SOURCE_ALPHA, LLRender::BF_ONE_MINUS_SOURCE_ALPHA);
        LLGLSLShader::unbind();
        releaseRaw(raw);
    }

    template<> template<>
    void object::test<18>()
    {
        set_test_name("copies, mipmaps, depth readbacks, queries and an upload fence");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        const Quad red = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 0, 0, 255 });
        Ref<Buffer> buffer = scene.vertices(red);
        encoder.beginRenderPass(scene.pass());
        encoder.setPipeline(scene.pipeline(*scene.color).get());
        encoder.setDepthStencilState(scene.device->getDepthStencilState({ true, true, CompareFunc::LessEqual }).get());
        encoder.setUniform(scene.color.get(), 0, { reinterpret_cast<const std::byte*>(IDENTITY), sizeof(IDENTITY) });
        encoder.setVertexBuffer(buffer.get(), red.streams);
        Ref<Query> samples = scene.device->createQuery(QueryType::SamplesPassed);
        encoder.beginQuery(samples.get());
        encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
        encoder.endQuery(samples.get());
        encoder.endRenderPass();
        ensure_equals("every pixel passed", samples->result(true), U64(64 * 64));

        Ref<Readback> depth = encoder.readback(scene.depth.get(), 0, 0, { 32, 32, 1, 1 },
                                               pixelLayoutFromGL(GL_DEPTH_COMPONENT, GL_FLOAT).value());
        F32 value = 0.f;
        memcpy(&value, depth->data().data(), 4);
        ensure("depth 0.5 at z 0", std::abs(value - 0.5f) < 0.001f);

        // A depth clear in a pass, which leaves raw GL's clear value alone.
        GLfloat clearValue = 0.f;
        glGetFloatv(GL_DEPTH_CLEAR_VALUE, &clearValue);
        encoder.beginRenderPass(scene.pass(false));
        encoder.clear(false, { 0.f, 0.f, 0.f, 0.f }, true, 0.25f);
        encoder.endRenderPass();
        depth = encoder.readback(scene.depth.get(), 0, 0, { 32, 32, 1, 1 },
                                 pixelLayoutFromGL(GL_DEPTH_COMPONENT, GL_FLOAT).value());
        memcpy(&value, depth->data().data(), 4);
        ensure("cleared to 0.25 in the pass", std::abs(value - 0.25f) < 0.001f);
        GLfloat clearAfter = -1.f;
        glGetFloatv(GL_DEPTH_CLEAR_VALUE, &clearAfter);
        ensure_equals("raw GL's clear value", clearAfter, clearValue);

        TextureDesc copyDesc = texture2D(64, 64);
        copyDesc.usage = TEXTURE_SAMPLED | TEXTURE_RENDER_TARGET | TEXTURE_READBACK;
        copyDesc.mipLevels = 7;
        Ref<Texture> copy = scene.device->createTexture(copyDesc, "copy");
        encoder.copyTexture(scene.target.get(), 0, 0, { 0, 0, 64, 64 }, copy.get(), 0, 0, 0, 0);
        encoder.generateMipmaps(copy.get());
        Ref<Readback> small = encoder.readback(copy.get(), 6, 0, { 0, 0, 1, 1 }, PixelLayout());
        std::array<U8, 4> top{};
        memcpy(top.data(), small->data().data(), 4);
        ensure("the 1x1 level is red: " + text(top), near(top, { 255, 0, 0, 255 }));

        TextureDesc fetched = texture2D(4, 4);
        fetched.usage = TEXTURE_SAMPLED | TEXTURE_READBACK;
        Ref<Texture> uploaded = scene.device->createTexture(fetched, "fetched");
        const std::vector<std::byte> pixels(4 * 4 * 4, std::byte(0x80));
        scene.device->uploadContext().uploadTexture(uploaded.get(), 0, 0, { 0, 0, 4, 4 }, PixelLayout(), pixels);
        Ref<Fence> fence = scene.device->uploadContext().submit();
        fence->wait();
        ensure("the upload's fence signals", fence->signaled());
        Ref<Readback> back = encoder.readback(uploaded.get(), 0, 0, { 3, 3, 1, 1 }, PixelLayout());
        std::array<U8, 4> texel{};
        memcpy(texel.data(), back->data().data(), 4);
        ensure("and the pixels are there: " + text(texel), near(texel, { 128, 128, 128, 128 }));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

