    template<> template<>
    void object::test<20>()
    {
        set_test_name("a program switch keeps the index buffer, which LLVertexBuffer::unbind lets go of");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        Ref<Program> blue = scene.device->createProgram(screenProgram("blueProgram", BLUE_FRAGMENT));
        ensure("linked", blue.notNull());
        const Quad red = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 0, 0, 255 });
        Ref<Buffer> buffer = scene.vertices(red);
        const U16 indices[6] = { 0, 1, 2, 2, 1, 3 };
        BufferDesc indexDesc;
        indexDesc.size = sizeof(indices);
        indexDesc.usage = BUFFER_INDEX;
        Ref<Buffer> indexBuffer = scene.device->createBuffer(indexDesc, std::as_bytes(std::span(indices)), "indices");
        encoder.beginRenderPass(scene.pass(true, false));
        encoder.setPipeline(scene.pipeline(*scene.color, false).get());
        encoder.setUniform(scene.color.get(), 0, { reinterpret_cast<const std::byte*>(IDENTITY), sizeof(IDENTITY) });
        encoder.setVertexBuffer(buffer.get(), red.streams);
        encoder.setIndexBuffer(indexBuffer.get(), IndexType::U16);
        encoder.drawIndexed(PrimitiveType::Triangles, 0, 6);
        encoder.setPipeline(scene.pipeline(*blue, false).get());
        ensure_equals("the index buffer is still bound", integer(GL_ELEMENT_ARRAY_BUFFER_BINDING),
                      GLint(GLNames::of(indexBuffer)));
        ensure_equals("and the vertex buffer", integer(GL_ARRAY_BUFFER_BINDING), GLint(GLNames::of(buffer)));
        encoder.drawIndexed(PrimitiveType::Triangles, 0, 6);
        encoder.endRenderPass();
        ensure("the second program drew: " + text(scene.pixel(32, 32)), near(scene.pixel(32, 32), { 0, 0, 255, 255 }));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

