    template<> template<>
    void object::test<22>()
    {
        set_test_name("unsigned uniforms, and integer targets cleared and read back as integers");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        Ref<Program> program = scene.device->createProgram(screenProgram("levelProgram", LEVEL_FRAGMENT));
        ensure("linked", program.notNull());
        const U32 index = uniformIndex(*program, "level");
        ensure("reflected", index < program->reflection().uniforms.size());
        const U32 level = 128;
        encoder.setUniform(program.get(), index, std::as_bytes(std::span(&level, 1)));
        const Quad q = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 255, 255, 255 });
        Ref<Buffer> buffer = scene.vertices(q);
        encoder.beginRenderPass(scene.pass(true, false));
        encoder.setPipeline(scene.pipeline(*program, false).get());
        encoder.setVertexBuffer(buffer.get(), q.streams);
        encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
        encoder.endRenderPass();
        ensure("the level as red: " + text(scene.pixel(32, 32)), near(scene.pixel(32, 32), { 128, 0, 0, 255 }));

        TextureDesc idsDesc = texture2D(4, 4, Format::R32Uint);
        idsDesc.usage = TEXTURE_RENDER_TARGET | TEXTURE_READBACK;
        Ref<Texture> ids = scene.device->createTexture(idsDesc, "ids");
        ensure("an integer target", ids.notNull());
        RenderPassDesc clear;
        clear.name = "ids";
        clear.colorCount = 1;
        clear.color[0].texture = ids;
        clear.color[0].load = LoadAction::Clear;
        clear.color[0].clear = { 7.f, 0.f, 0.f, 0.f };
        const PixelLayout uint = pixelLayoutFromGL(GL_RED, GL_UNSIGNED_INT).value();
        auto idAt = [&encoder, &ids, &uint]()
        {
            Ref<Readback> readback = encoder.readback(ids.get(), 0, 0, { 1, 1, 1, 1 }, uint);
            U32 value = 0;
            if (readback.notNull() && readback->data().size() == 4)
            {
                memcpy(&value, readback->data().data(), 4);
            }
            return value;
        };
        encoder.beginRenderPass(clear);
        encoder.endRenderPass();
        ensure_equals("the load action cleared to 7", idAt(), 7u);
        clear.color[0].load = LoadAction::Load;
        encoder.beginRenderPass(clear);
        encoder.clear(true, { 9.f, 0.f, 0.f, 0.f }, false, 1.f);
        encoder.endRenderPass();
        ensure_equals("a clear in the pass to 9", idAt(), 9u);
        // [Viewer Lab] The encoder's own rule for integer textures (P2-11a's tests-3, P2-R1): MIN and MAG NEAREST, also when
        // the sampling asks for MAG LINEAR; setTexture in a pass binds at once.
        Ref<Texture> integral = scene.device->createTexture(texture2D(4, 4, Format::R32Uint), "integer sampling");
        ensure("an integer texture", integral.notNull());
        for (const MagFilter asked : { MagFilter::Linear, MagFilter::Nearest })
        {
            const std::string at = asked == MagFilter::Linear ? "integer, MAG LINEAR asked: " : "integer, MAG NEAREST asked: ";
            SamplerDesc sampling;
            sampling.filter = Filter::Trilinear;
            sampling.magFilter = asked;
            encoder.beginRenderPass(scene.pass(true, false));
            encoder.setTexture(0, integral.get(), sampling);
            GLint min = 0;
            GLint mag = 0;
            {
                ScratchBinding binding(GL_TEXTURE_2D, GLNames::of(integral));
                glGetTexParameteriv(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, &min);
                glGetTexParameteriv(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, &mag);
            }
            encoder.setTexture(0, nullptr, SamplerDesc());
            encoder.endRenderPass();
            ensure_equals(at + "MIN NEAREST", min, GLint(GL_NEAREST));
            ensure_equals(at + "MAG NEAREST", mag, GLint(GL_NEAREST));
        }
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<23>()
    {
        set_test_name("bindings are set again when a pass begins, after raw GL between passes");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        Ref<Texture> checker = scene.device->createTexture(texture2D(2, 2), "checker");
        encoder.uploadTexture(checker.get(), 0, 0, { 0, 0, 2, 2 }, PixelLayout(), std::as_bytes(std::span(CHECKER)));
        Ref<Texture> other = scene.device->createTexture(texture2D(2, 2), "other");
        const Quad q = quad(-1.f, -1.f, 1.f, 1.f, 0.f, { 255, 255, 255, 255 });
        Ref<Buffer> buffer = scene.vertices(q);
        LLTexUnit* unit = gGL.getTexUnit(0);
        GLNames::bind(unit, LLTexUnit::TT_TEXTURE, GLNames::of(other));

        // Outside a pass the setters only record.
        SamplerDesc point;
        point.filter = Filter::Point;
        encoder.setPipeline(scene.pipeline(*scene.textured, false).get());
        encoder.setSamplerChannel(scene.textured.get(), 0, 0);
        encoder.setTexture(0, checker.get(), point);
        encoder.setVertexBuffer(buffer.get(), q.streams);
        ensure_equals("unit 0 keeps raw GL's texture", unit->getCurrTexture(), GLNames::of(other));
        for (int pass = 0; pass < 2; ++pass)
        {
            const std::string which = "pass " + std::to_string(pass) + ": ";
            encoder.beginRenderPass(scene.pass(true, false));
            encoder.draw(PrimitiveType::TriangleStrip, 0, 4);
            encoder.endRenderPass();
            ensure(which + "bottom left red: " + text(scene.pixel(8, 8)), near(scene.pixel(8, 8), { 255, 0, 0, 255 }));
            ensure(which + "top right white", near(scene.pixel(56, 56), { 255, 255, 255, 255 }));
            // Raw GL between the passes binds its own.
            GLNames::bind(unit, LLTexUnit::TT_TEXTURE, GLNames::of(other));
            LLVertexBuffer::unbind();
            LLGLSLShader::unbind();
        }
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<24>()
    {
        set_test_name("GL objects let go of on another thread are deleted on the main thread at a frame end");
        ensure("the tests run on the main thread", on_main_thread());
        Ref<Device> device = glDevice();
        Ref<Program> program = device->createProgram(programDesc("threadProgram"));
        Ref<Texture> texture = device->createTexture(texture2D(4, 4), "threadTexture");
        BufferDesc bufferDesc;
        bufferDesc.size = 64;
        Ref<Buffer> buffer = device->createBuffer(bufferDesc, {}, "threadBuffer");
        ensure("created", program.notNull() && texture.notNull() && buffer.notNull());
        const GLuint programName = GLNames::of(program);
        const GLuint textureName = GLNames::of(texture);
        const GLuint bufferName = GLNames::of(buffer);
        // A thread with no GL context lets go of the last references.
        std::thread([&program, &texture, &buffer]
        {
            program = nullptr;
            texture = nullptr;
            buffer = nullptr;
        }).join();
        ensure("the program waits for the main thread", glIsProgram(programName));
        ensure("so does the texture", glIsTexture(textureName));
        ensure("and the buffer", glIsBuffer(bufferName));
        device->endFrame();
        ensure("the program is deleted at the frame end", !glIsProgram(programName));
        // LLVertexBuffer deletes a frame's names three frames later, when it next deletes some.
        for (int frame = 0; frame < 3; ++frame)
        {
            LLImageGL::updateClass();
        }
        device->createBuffer(bufferDesc, {}, "probe"); // let go of at once, on the main thread
        ensure("the buffer three frames later, as today", !glIsBuffer(bufferName));
        for (int frame = 0; frame < 2; ++frame)
        {
            LLImageGL::updateClass();
        }
        ensure("the texture a few frames later, as today", !glIsTexture(textureName));
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

