    template<> template<>
    void object::test<26>()
    {
        set_test_name("texture units keep their mip flag, which LLTexUnit's filters read");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        TextureDesc mipDesc = texture2D(8, 8);
        mipDesc.mipLevels = 4;
        Ref<Texture> mipped = scene.device->createTexture(mipDesc, "mipped");
        LLTexUnit* unit0 = gGL.getTexUnit(0);
        GLNames::bind(unit0, LLTexUnit::TT_TEXTURE, GLNames::of(mipped), true);
        ensure("another", scene.device->createTexture(texture2D(4, 4), "another").notNull());
        ensure_equals("unit 0 has its texture back", unit0->getCurrTexture(), GLNames::of(mipped));
        // As LLImageGL::setFilteringOption sets a filter on the bound texture.
        unit0->activate();
        unit0->setTextureFilteringOption(LLTexUnit::TFO_TRILINEAR);
        GLint filter = 0;
        glGetTexParameteriv(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, &filter);
        ensure_equals("with its mip flag", filter, GLint(GL_LINEAR_MIPMAP_LINEAR));

        // Raw GL bound the texture without the flag, as bindManual(U32, U32) does.
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        LLTexUnit* unit2 = gGL.getTexUnit(2);
        GLNames::bind(unit2, LLTexUnit::TT_TEXTURE, GLNames::of(mipped));
        SamplerDesc trilinear;
        trilinear.filter = Filter::Trilinear;
        encoder.beginRenderPass(scene.pass());
        encoder.setTexture(2, mipped.get(), trilinear);
        encoder.endRenderPass();
        unit2->activate();
        filter = 0;
        glGetTexParameteriv(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, &filter);
        ensure_equals("trilinear uses the mips", filter, GLint(GL_LINEAR_MIPMAP_LINEAR));
        encoder.setTexture(2, nullptr, trilinear);
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
    }

    template<> template<>
    void object::test<27>()
    {
        set_test_name("a pass begins with the default dynamic state and gives raw GL's back, the viewport too");
        Scene scene;
        Encoder& encoder = scene.device->encoder();
        LLRenderTarget raw;
        ensure("a raw target", raw.allocate(64, 64, GL_RGBA, true));
        raw.bindTarget();
        glViewport(4, 8, 16, 32); // a part of the target, as LLViewerDynamicTexture sets one
        {
            LLGLEnable scissor(GL_SCISSOR_TEST);
            LLGLEnable cull(GL_CULL_FACE);
            LLGLEnable offset(GL_POLYGON_OFFSET_FILL);
            LLGLEnable offsetLines(GL_POLYGON_OFFSET_LINE);
            LLGLEnable clamp(GL_DEPTH_CLAMP);
            glPolygonOffset(2.f, 3.f);
            glPolygonMode(GL_FRONT_AND_BACK, GL_LINE);
            glPointSize(5.f);

            encoder.beginRenderPass(scene.pass());
            ensure("no scissor", !glIsEnabled(GL_SCISSOR_TEST));
            ensure("no culling", !glIsEnabled(GL_CULL_FACE));
            ensure("no depth bias", !glIsEnabled(GL_POLYGON_OFFSET_FILL) && !glIsEnabled(GL_POLYGON_OFFSET_LINE));
            GLfloat factor = -1.f;
            GLfloat units = -1.f;
            glGetFloatv(GL_POLYGON_OFFSET_FACTOR, &factor);
            glGetFloatv(GL_POLYGON_OFFSET_UNITS, &units);
            ensure("and none set", factor == 0.f && units == 0.f);
            ensure("no depth clamp", !glIsEnabled(GL_DEPTH_CLAMP));
            GLfloat lineWidth = 0.f;
            glGetFloatv(GL_LINE_WIDTH, &lineWidth);
            ensure_equals("lines of 1 pixel", lineWidth, 1.f);
            GLint mode[2] = {};
            glGetIntegerv(GL_POLYGON_MODE, mode);
            ensure_equals("filled", mode[0], GLint(GL_FILL));
            GLfloat size = 0.f;
            glGetFloatv(GL_POINT_SIZE, &size);
            ensure_equals("points of 1 pixel", size, 1.f);
            GLint viewport[4] = {};
            glGetIntegerv(GL_VIEWPORT, viewport);
            ensure("the whole attachment", viewport[0] == 0 && viewport[1] == 0 && viewport[2] == 64 && viewport[3] == 64);
            ensure_equals("LLGLState's cache matches GL in the pass", StateCache::mismatch(), std::string());
            encoder.endRenderPass();

            ensure("raw GL's scissor", glIsEnabled(GL_SCISSOR_TEST));
            ensure("culling", glIsEnabled(GL_CULL_FACE));
            ensure("depth bias", glIsEnabled(GL_POLYGON_OFFSET_FILL) && glIsEnabled(GL_POLYGON_OFFSET_LINE));
            glGetFloatv(GL_POLYGON_OFFSET_FACTOR, &factor);
            glGetFloatv(GL_POLYGON_OFFSET_UNITS, &units);
            ensure("its values", factor == 2.f && units == 3.f);
            ensure("depth clamp", glIsEnabled(GL_DEPTH_CLAMP));
            glGetIntegerv(GL_POLYGON_MODE, mode);
            ensure_equals("lines", mode[0], GLint(GL_LINE));
            glGetFloatv(GL_POINT_SIZE, &size);
            ensure_equals("its point size", size, 5.f);
            glGetIntegerv(GL_VIEWPORT, viewport);
            ensure("and its viewport", viewport[0] == 4 && viewport[1] == 8 && viewport[2] == 16 && viewport[3] == 32);
            ensure_equals("LLGLState's cache matches GL after it", StateCache::mismatch(), std::string());
            glPolygonMode(GL_FRONT_AND_BACK, GL_FILL);
            glPointSize(1.f);
            glPolygonOffset(0.f, 0.f);
        }
        ensure_equals("no GL error", glGetError(), GLenum(GL_NO_ERROR));
        releaseRaw(raw);
    }

