        set_test_name("LLImageGL::setSubImageFromFrameBuffer from a bound LLRenderTarget into an LLImageGL with a device "
                      "texture through the copy facade (P2-08): tracked +1, the tracker's transfers +1, test<2>'s texels");
        ensure_equals("no GL error before", glGetError(), GLenum(GL_NO_ERROR));
